() => {
  // Try to find the Cloudflare challenge iframe
  const iframes = document.querySelectorAll('iframe');
  const result = {
    iframeCount: iframes.length,
    iframes: []
  };
  for (let i = 0; i < iframes.length; i++) {
    result.iframes.push({
      src: iframes[i].src,
      title: iframes[i].title,
      id: iframes[i].id
    });
  }
  // Check for challenge elements
  const cfElements = document.querySelectorAll('[id*="cf"], [class*="cf-"], [class*="cloudflare"]');
  result.cfElements = cfElements.length;
  // Get the input
  const input = document.querySelector('input[type="checkbox"]');
  if (input) {
    result.inputExists = true;
    result.inputOuterHTML = input.outerHTML.substring(0, 500);
  }
  return result;
}

() => {
  // Try to click the checkbox directly
  const checkbox = document.querySelector('input[type="checkbox"]');
  if (checkbox) {
    // Try multiple ways to click
    checkbox.click();
    return {
      clicked: true,
      checked: checkbox.checked,
      ariaLabel: checkbox.getAttribute('aria-label')
    };
  }
  return { clicked: false };
}

() => {
  const checkbox = document.querySelector('input[type="checkbox"]');
  if (!checkbox) return { found: false };

  // Simulate mouse over and click
  const rect = checkbox.getBoundingClientRect();
  const x = rect.left + rect.width / 2;
  const y = rect.top + rect.height / 2;

  // Dispatch mouse events
  ['mouseover', 'mousedown', 'mouseup', 'click'].forEach(eventType => {
    const event = new MouseEvent(eventType, {
      bubbles: true,
      cancelable: true,
      view: window,
      clientX: x,
      clientY: y
    });
    checkbox.dispatchEvent(event);
  });

  return {
    found: true,
    checked: checkbox.checked,
    position: { x, y },
    visible: rect.width > 0 && rect.height > 0
  };
}
